def components(g,val):
    H,W=len(g),len(g[0]); seen=set(); comps=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]==val and (r,c) not in seen:
                stack=[(r,c)]; seen.add((r,c)); comp=[]
                while stack:
                    y,x=stack.pop(); comp.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and g[ny][nx]==val and (ny,nx) not in seen:
                            seen.add((ny,nx)); stack.append((ny,nx))
                comps.append(comp)
    return comps

def spans(comp,H,W):
    rows={r for r,c in comp}; cols={c for r,c in comp}
    return (0 in rows and H-1 in rows) or (0 in cols and W-1 in cols)

