def straight_span_mask(g,val):
    H,W=len(g),len(g[0])
    m=[[False]*W for _ in range(H)]
    for r in range(H):
        if all(g[r][c]==val for c in range(W)):
            for c in range(W): m[r][c]=True
    for c in range(W):
        if all(g[r][c]==val for r in range(H)):
            for r in range(H): m[r][c]=True
    return m

