def run_rule(g, val, thr):
    H,W=len(g),len(g[0])
    hlen=[[1]*W for _ in range(H)]; vlen=[[1]*W for _ in range(H)]
    for r in range(H):
        for c in range(1,W):
            if g[r][c]==val and g[r][c-1]==val: hlen[r][c]=hlen[r][c-1]+1
    for r in range(H):
        c=W-1
        while c>=0:
            if g[r][c]==val and c+1<W and g[r][c+1]==val: hlen[r][c]=max(hlen[r][c],hlen[r][c+1]+1)
            c-=1
    for c in range(W):
        for r in range(1,H):
            if g[r][c]==val and g[r-1][c]==val: vlen[r][c]=vlen[r-1][c]+1
    for c in range(W):
        r=H-1
        while r>=0:
            if g[r][c]==val and r+1<H and g[r+1][c]==val: vlen[r][c]=max(vlen[r][c],vlen[r+1][c]+1)
            r-=1
    return [[2 if g[r][c]==val and (hlen[r][c]>=thr or vlen[r][c]>=thr) else g[r][c] for c in range(W)] for r in range(H)]

